scripts.escape-game:
const tracks = {
  bgm: 'sounds/bgm/tense.wav',
  correct: 'sounds/sfx/correct.wav',
  wrong: 'sounds/sfx/wrong.wav',
  clear: 'sounds/sfx/fanfare.wav'
};
const configuredQuestions = sg.get('questions');
const valid = Array.isArray(configuredQuestions) && configuredQuestions.length > 0 && configuredQuestions.every(question => (
  question && typeof question.prompt === 'string' && question.prompt.trim() !== '' &&
  Array.isArray(question.options) && question.options.length >= 2 && question.options.length <= 4 &&
  question.options.every(option => typeof option === 'string' && option.trim() !== '') &&
  Number.isInteger(question.answer) && question.answer >= 0 && question.answer < question.options.length
));
const questions = valid ? configuredQuestions : [];
const total = questions.length;
const gap = Math.min(7, 128 / Math.max(1, total));
const segmentWidth = (321 - gap * Math.max(0, total - 1)) / Math.max(1, total);
const segments = questions.map((question, index) => ({
  id: `lock-segment-${index}`, type: 'shape', shape: 'rect',
  x: 867 + index * (segmentWidth + gap), y: 675, w: segmentWidth, h: 8,
  z: 2, fill: '#293D5A', radius: Math.min(4, segmentWidth / 2)
}));
if (segments.length) sg.put(segments);

const initialMission = { stage: 'intro', index: 0, mistakes: [], solved: false, sound: true };
const optionPrefixes = ['A', 'B', 'C', 'D'];
function render() {
  const mission = sg.get('mission') || initialMission;
  const playing = valid && mission.stage === 'playing';
  const cleared = valid && mission.stage === 'cleared';
  const question = questions[mission.index];
  const unlocked = cleared ? total : mission.index + Number(mission.solved);
  const hatchReady = valid && unlocked === total;
  const feedbackVisible = playing && (mission.solved || mission.mistakes.length > 0);
  const hasHint = typeof question?.hint === 'string' && question.hint.trim() !== '';
  const detail = mission.solved ? (question?.explanation || '') : (hasHint ? question.hint : '別の答えを選んでみよう。');
  const statusText = cleared ? '開放済み' : hatchReady ? '開放可能' : 'ロック中';

  sg.update('sound', { label: mission.sound ? '音声 ON' : '音声 OFF', color: mission.sound ? '#192A46' : '#232B3F' });
  sg.update('terminal-label', { text: playing ? `ロック ${String(mission.index + 1).padStart(2, '0')} / ${String(total).padStart(2, '0')}${question.topic ? '　·　' + question.topic : ''}` : cleared ? 'ミッション完了' : '脱出手順' });
  sg.update('intro-title', {
    visible: !playing,
    text: !valid ? '問題を読み込めません' : cleared ? '脱出成功！' : `${total}つのロックを解除`,
    color: cleared ? '#A4F4DD' : '#F0F6FF'
  });
  sg.update('intro-body', {
    visible: !playing,
    text: !valid ? '各問題に問題文、2〜4個の選択肢、正解の番号を設定してね。' : cleared ? `すべてのロックを解除して、宇宙基地から脱出した。\nミッション達成　${total} / ${total} 問正解` : '正解するたびに、ハッチのロックが1つ開く。\nまちがえても、何度でも挑戦できる。'
  });
  sg.update('begin', { visible: valid && mission.stage === 'intro' });
  sg.update('replay', { visible: cleared });
  sg.update('prompt', { visible: playing, text: playing ? question.prompt : '' });
  optionPrefixes.forEach((prefix, index) => {
    const option = question?.options[index];
    const correct = mission.solved && index === question?.answer;
    const wrong = mission.mistakes.includes(index);
    sg.update(`answer-${index}`, {
      visible: playing && Boolean(option),
      disabled: mission.solved || wrong,
      label: option ? `${prefix}　${option}` : '',
      color: correct ? '#185742' : wrong ? '#412A3D' : '#1C2B49',
      text_color: correct ? '#BAFCE1' : wrong ? '#FFBAC6' : '#E7F0FF'
    });
  });
  sg.update('feedback-panel', { visible: feedbackVisible, fill: mission.solved ? '#14352F' : '#332439' });
  sg.update('feedback-title', {
    visible: feedbackVisible,
    color: mission.solved ? '#8EF3CB' : '#FFB3C5',
    text: mission.solved ? '正解！ ロック解除' : hasHint ? '不正解　·　ヒント' : '不正解'
  });
  sg.update('feedback-detail', { visible: feedbackVisible && Boolean(detail), text: detail });
  sg.update('next', { visible: playing && mission.solved, label: hatchReady ? 'ハッチを開ける →' : '次のロックへ →' });
  sg.update('hatch-status', { text: statusText, color: hatchReady ? '#A0F3D4' : '#FFB9B9' });
  sg.update('hatch-status-bg', { fill: hatchReady ? '#1B493F' : '#422D41' });
  sg.update('hatch-open', { visible: hatchReady });
  sg.update('hatch-lock', { visible: !hatchReady });
  sg.update('progress', { text: `${unlocked} / ${total}` });
  segments.forEach((segment, index) => sg.update(segment.id, { fill: index < unlocked ? '#75EBD8' : '#293D5A' }));
}

function begin() {
  const mission = sg.get('mission');
  if (!valid || mission.stage === 'playing') return;
  sg.set('mission', { ...initialMission, stage: 'playing', sound: mission.sound });
  if (mission.sound) sg.bgm(tracks.bgm, { volume: 0.28, fade_ms: 650 });
}

function pick(index) {
  const mission = sg.get('mission');
  if (mission.stage !== 'playing' || mission.solved || mission.mistakes.includes(index)) return;
  const question = questions[mission.index];
  if (index >= question.options.length) return;
  if (index === question.answer) {
    sg.set('mission', { ...mission, solved: true });
    if (mission.sound) sg.sound(tracks.correct, 0.7);
  } else {
    sg.set('mission', { ...mission, mistakes: [...mission.mistakes, index] });
    if (mission.sound) sg.sound(tracks.wrong, 0.65);
  }
}

function advance() {
  const mission = sg.get('mission');
  if (mission.stage !== 'playing' || !mission.solved) return;
  if (mission.index + 1 < total) {
    sg.set('mission', { ...mission, index: mission.index + 1, solved: false, mistakes: [] });
    return;
  }
  sg.set('mission', { ...mission, stage: 'cleared' });
  if (mission.sound) {
    sg.bgm(null, { fade_ms: 450 });
    sg.sound(tracks.clear, 0.75);
  }
}

function toggleSound() {
  const mission = sg.get('mission');
  const sound = !mission.sound;
  sg.set('mission', { ...mission, sound });
  if (mission.stage === 'playing') {
    sg.bgm(sound ? tracks.bgm : null, { volume: 0.28, fade_ms: 200 });
  }
}

sg.on('press', 'begin', begin);
sg.on('press', 'replay', begin);
sg.on('press', 'sound', toggleSound);
sg.on('press', 'next', advance);
optionPrefixes.forEach((prefix, index) => sg.on('press', `answer-${index}`, () => pick(index)));
sg.on('state', render);
sg.set('mission', initialMission);
render();
